    @push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const button=document.getElementById('copy-servant-link'),input=document.getElementById('servant-private-url'),feedback=document.getElementById('copy-servant-feedback');button?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(input.value)}catch{input.select();document.execCommand('copy')}feedback?.classList.remove('hidden');button.querySelector('span').textContent='Copiado';setTimeout(()=>{feedback?.classList.add('hidden');button.querySelector('span').textContent='Copiar'},2200)})});</script>@endpush
